def safe_tag(value):
    return re.sub(r"[^A-Za-z0-9]+", "_", str(value)).strip("_") or "default"


def dataset_root(data_name, variant):
    root = DATASETS_BASE_DIR / str(data_name).strip()
    if variant is not None:
        root = root / str(variant).strip()
    return root.resolve()


