def section(
    title: str,
) -> None:
    print(
        "\n" + "=" * 80,
        flush=True,
    )

    print(
        title,
        flush=True,
    )

    print(
        "=" * 80,
        flush=True,
    )


def run_command(
    command,
    title=None,
    check=True,
    cwd=None,
    env=None,
    log_path=None,
):
    """
    Komutu çalıştırır.

    stdout ve stderr çıktıları Colab ekranına
    satır satır ve anlık biçimde aktarılır.
    """

    if title:
        section(
            title
        )

    if cwd is None:
        cwd = WORK_PROJECT_DIR

    command = [
        str(value)
        for value in command
    ]

    print(
        "$",
        " ".join(command),
        flush=True,
    )

    process_env = os.environ.copy()

    if env:
        process_env.update(
            env
        )

    start_time = time.time()

    log_file = None

    try:
        if log_path is not None:
            log_path = Path(
                log_path
            )

            log_path.parent.mkdir(
                parents=True,
                exist_ok=True,
            )

            log_file = log_path.open(
                "w",
                encoding="utf-8",
            )

        process = subprocess.Popen(
            command,
            cwd=str(cwd),
            env=process_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )

        if process.stdout is None:
            raise RuntimeError(
                "Alt süreç çıktısı okunamadı."
            )

        for line in process.stdout:
            print(
                line,
                end="",
                flush=True,
            )

            if log_file is not None:
                log_file.write(
                    line
                )

                log_file.flush()

        return_code = process.wait()

    except FileNotFoundError as exc:
        if check:
            raise RuntimeError(
                "Komut çalıştırılamadı:\n"
                + " ".join(command)
            ) from exc

        return 127, 0.0

    finally:
        if log_file is not None:
            log_file.close()

    elapsed = (
        time.time()
        - start_time
    )

    print(
        f"\nElapsed seconds: {elapsed:.2f}",
        flush=True,
    )

    print(
        f"Return code    : {return_code}",
        flush=True,
    )

    if (
        check
        and return_code != 0
    ):
        raise RuntimeError(
            "Komut başarısız oldu:\n"
            + " ".join(command)
            + f"\nReturn code: {return_code}"
        )

    return return_code, elapsed


def remove_path(
    path,
):
    path = Path(
        path
    )

    if path.is_symlink() or path.is_file():
        path.unlink(
            missing_ok=True
        )

    elif path.is_dir():
        shutil.rmtree(
            path,
            ignore_errors=True,
        )


def clear_python_cache(
    project_dir,
):
    project_dir = Path(
        project_dir
    )

    if not project_dir.exists():
        return

    for cache_dir in project_dir.rglob(
        "__pycache__"
    ):
        shutil.rmtree(
            cache_dir,
            ignore_errors=True,
        )

    for pyc_file in project_dir.rglob(
        "*.pyc"
    ):
        try:
            pyc_file.unlink()

        except OSError:
            pass


# ============================================================
# 6. IMAGE DATASET HELPERS
# ============================================================

IMAGE_EXTENSIONS = {
    ".png",
    ".jpg",
    ".jpeg",
    ".bmp",
    ".tif",
    ".tiff",
}


def indexed_images(
    folder,
):
    """
    Geçerli görüntüleri dosya gövdesine göre indeksler.

    macOS AppleDouble dosyaları (._*), gizli dosyalar ve birkaç yüz
    baytlık sahte görüntüler veri kümesine dahil edilmez.
    """

    folder = Path(folder)

    if not folder.is_dir():
        return {}, []

    index = {}
    duplicates = []
    ignored_hidden = 0
    ignored_small = 0

    for path in sorted(folder.iterdir()):
        if not path.is_file():
            continue

        if path.name.startswith("."):
            ignored_hidden += 1
            continue

        if path.suffix.lower() not in IMAGE_EXTENSIONS:
            continue

        # AppleDouble dosyaları çoğunlukla 187 bayt civarındadır.
        # 1 KB altındaki dosyalar gerçek eğitim görüntüsü kabul edilmez.
        try:
            if path.stat().st_size < 1024:
                ignored_small += 1
                continue
        except OSError:
            continue

        key = path.stem.casefold()

        if key in index:
            duplicates.append((index[key].name, path.name))
        else:
            index[key] = path

    if ignored_hidden or ignored_small:
        print(
            f"Ignored invalid files in {folder}: "
            f"hidden={ignored_hidden}, small={ignored_small}",
            flush=True,
        )

    return index, duplicates


def check_image_pair_folders(
    low_dir,
    high_dir,
    split_name,
):
    """
    Low ve Normal/High görüntü klasörlerini kontrol eder.
    """

    low_dir = Path(
        low_dir
    )

    high_dir = Path(
        high_dir
    )

    if not low_dir.is_dir():
        raise FileNotFoundError(
            f"{split_name} Low klasörü yok:\n"
            f"{low_dir}"
        )

    if not high_dir.is_dir():
        raise FileNotFoundError(
            f"{split_name} High klasörü yok:\n"
            f"{high_dir}"
        )

    low_index, low_duplicates = indexed_images(
        low_dir
    )

    high_index, high_duplicates = indexed_images(
        high_dir
    )

    matched_keys = sorted(
        low_index.keys()
        & high_index.keys()
    )

    only_low = sorted(
        low_index.keys()
        - high_index.keys()
    )

    only_high = sorted(
        high_index.keys()
        - low_index.keys()
    )

    print(
        f"\n{split_name}",
        flush=True,
    )

    print(
        "Low directory :",
        low_dir,
        flush=True,
    )

    print(
        "High directory:",
        high_dir,
        flush=True,
    )

    print(
        "Low images    :",
        len(low_index),
        flush=True,
    )

    print(
        "High images   :",
        len(high_index),
        flush=True,
    )

    print(
        "Matched pairs :",
        len(matched_keys),
        flush=True,
    )

    if not low_index:
        raise RuntimeError(
            f"{split_name} Low klasörü boş:\n"
            f"{low_dir}"
        )

    if not high_index:
        raise RuntimeError(
            f"{split_name} High klasörü boş:\n"
            f"{high_dir}"
        )

    if not matched_keys:
        low_examples = [
            path.name
            for path in list(
                low_index.values()
            )[:10]
        ]

        high_examples = [
            path.name
            for path in list(
                high_index.values()
            )[:10]
        ]

        raise RuntimeError(
            f"{split_name}: eşleşen görüntü çifti bulunamadı.\n\n"
            f"Low klasörü : {low_dir}\n"
            f"High klasörü: {high_dir}\n"
            f"Low sayısı  : {len(low_index)}\n"
            f"High sayısı : {len(high_index)}\n\n"
            f"Low örnek dosyalar : {low_examples}\n"
            f"High örnek dosyalar: {high_examples}\n\n"
            "Muhtemel nedenler:\n"
            "1. Low ve Normal klasörleri farklı veri kümelerine ait.\n"
            "2. Low ve Normal dosyalarının gövde adları uyuşmuyor.\n"
            "3. Colab oturumunda önceki çalıştırmadan kalan değişkenler var."
        )

    if (
        low_duplicates
        or high_duplicates
    ):
        raise RuntimeError(
            f"{split_name}: aynı gövde adına sahip "
            "yinelenen görüntüler bulundu.\n"
            f"Low örnekleri : {low_duplicates[:10]}\n"
            f"High örnekleri: {high_duplicates[:10]}"
        )

    if only_low:
        print(
            "UYARI: yalnızca Low tarafında "
            f"{len(only_low)} görüntü var.",
            flush=True,
        )

    if only_high:
        print(
            "UYARI: yalnızca High tarafında "
            f"{len(only_high)} görüntü var.",
            flush=True,
        )

    if (
        FAIL_ON_UNPAIRED_IMAGES
        and (
            only_low
            or only_high
        )
    ):
        raise RuntimeError(
            f"{split_name}: eşleşmeyen görüntüler bulundu."
        )

    return {
        "low_index": low_index,
        "high_index": high_index,
        "matched_keys": matched_keys,
        "low_count": len(
            low_index
        ),
        "high_count": len(
            high_index
        ),
        "matched_count": len(
            matched_keys
        ),
        "only_low_count": len(
            only_low
        ),
        "only_high_count": len(
            only_high
        ),
    }


# ============================================================
# 7. DIRECTORY LINK HELPERS
# ============================================================

def create_directory_link(
    source,
    destination,
):
    """
    Dataset klasörünü yalnızca yerel /content/RetinexNet çalışma
    klasörüne bağlar. Kaynak ve hedef aynıysa dataset'i korumak için durur.
    """

    source = Path(source).resolve()
    destination = Path(destination).absolute()

    work_root = Path("/content/RetinexNet").absolute()

    print(
        "Preparing link:",
        destination,
        "->",
        source,
        flush=True,
    )

    if destination == source:
        raise RuntimeError(
            "GÜVENLİK HATASI: Symlink kaynak ve hedef yolu aynı.\n"
            f"Kaynak: {source}\n"
            f"Hedef : {destination}\n"
            "Dataset klasörünün silinmesini önlemek için işlem durduruldu."
        )

    try:
        destination.relative_to(work_root)
    except ValueError as exc:
        raise RuntimeError(
            "Symlink hedefi /content/RetinexNet dışında olamaz.\n"
            f"Hedef: {destination}"
        ) from exc

    if not source.is_dir():
        raise FileNotFoundError(
            "Symlink kaynağı bulunamadı:\n"
            f"{source}"
        )

    remove_path(destination)

    destination.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    os.symlink(
        str(source),
        str(destination),
        target_is_directory=True,
    )

    if not destination.is_symlink():
        raise RuntimeError(
            f"Symlink oluşturulamadı: {destination}"
        )

    resolved_target = destination.resolve()

    if resolved_target != source:
        raise RuntimeError(
            "Symlink yanlış hedefe bağlandı.\n"
            f"Beklenen: {source}\n"
            f"Bulunan : {resolved_target}"
        )

    print(
        "Linked:",
        destination,
        "->",
        resolved_target,
        flush=True,
    )


def create_empty_directory(
    path,
):
    path = Path(
        path
    )

    remove_path(
        path
    )

    path.mkdir(
        parents=True,
        exist_ok=True,
    )


